type PluralForms = { other: string } & Partial<Record<Intl.LDMLPluralRule, string>> & {
    [exact: `=${number}`]: string;
  };

function cached<F>(cache: Map<string, F>, key: string, create: () => F) {
  const existing = cache.get(key);
  if (existing) return existing;
  const created = create();
  cache.set(key, created);
  return created;
}

const pluralRules = new Map<string, Intl.PluralRules>();
const numberFormats = new Map<string, Intl.NumberFormat>();
const dateFormats = new Map<string, Intl.DateTimeFormat>();

/** `=N` forms win over the locale's plural category, which falls back to `other`. */
export function plural(locale: string, n: number, forms: PluralForms) {
  const exact = forms[`=${n}`];
  if (exact !== undefined) return exact;
  const rules = cached(pluralRules, locale, () => new Intl.PluralRules(locale));
  return forms[rules.select(n)] ?? forms.other;
}

export function number(locale: string, value: number, options?: Intl.NumberFormatOptions) {
  const key = `${locale}|${JSON.stringify(options)}`;
  return cached(numberFormats, key, () => new Intl.NumberFormat(locale, options)).format(value);
}

export function currency(
  locale: string,
  value: number,
  currencyCode: string,
  options?: Intl.NumberFormatOptions,
) {
  return number(locale, value, { ...options, style: "currency", currency: currencyCode });
}

export function date(locale: string, value: Date | number, options?: Intl.DateTimeFormatOptions) {
  const key = `${locale}|${JSON.stringify(options)}`;
  return cached(dateFormats, key, () => new Intl.DateTimeFormat(locale, options)).format(value);
}

/** A namespace as components consume it: sections like `labels`, `formats`, `functions`. */
export type NamespaceConfig = Record<string, object>;

/** In a dictionary, `functions` is a factory over the merged sibling sections. */
export type DictionaryNamespace<C extends NamespaceConfig> = {
  [K in keyof C]: K extends "functions" ? (sections: Omit<C, "functions">) => C[K] : C[K];
};

/** What a component's `i18n` prop and the provider's `overrides` take. */
export type NamespaceOverrides<C extends NamespaceConfig> = { [K in keyof C]?: Partial<C[K]> };

declare global {
  /** One entry per installed item with text, added by the item's own file. */
  interface FmaNamespaces {}
}

/** A namespace in a language pack: anything left out falls back, functions included. */
export type PackNamespace<C extends NamespaceConfig> = {
  [K in keyof C]?: K extends "functions"
    ? (sections: Omit<C, "functions">) => Partial<C[K]>
    : Partial<C[K]>;
};

/** What an item that isn't installed looks like to a pack: it has no types to offer. */
export type LooseMessages = { [key: string]: LooseMessage };

type LooseMessage =
  | string
  | readonly string[]
  | LooseMessages
  | undefined
  // biome-ignore lint/suspicious/noExplicitAny: an item that isn't installed has no types to offer
  | ((...args: any[]) => LooseMessage);

/** A language pack. It brings every item's texts, whichever are installed. */
export type FmaMessagesPack = {
  [K in keyof FmaNamespaces]?: PackNamespace<FmaNamespaces[K]>;
} & { [namespace: string]: LooseMessages | undefined };

export type FmaOverrides = {
  [K in keyof FmaNamespaces]?: NamespaceOverrides<FmaNamespaces[K]>;
};

/** A namespace of a language pack: checked when the item is installed, loose when it isn't. */
export type FmaNamespaceMessages<K extends string> = K extends keyof FmaNamespaces
  ? PackNamespace<FmaNamespaces[K]>
  : LooseMessages;

export function defineFmaNamespace<K extends string>(
  _namespace: K,
  messages: FmaNamespaceMessages<K>,
) {
  return messages;
}

export * from "./i18n-format";
export * from "./i18n-types";
export * from "./merge";
export * from "./negotiate";
export * from "./react";
export * from "./store";

import type { NamespaceConfig, NamespaceOverrides, PackNamespace } from "./i18n-types";

type Layer = Record<string, unknown> | undefined;
type Factory = (sections: Record<string, object>) => object;

// A trie over the layers' identities: the same layers give the same object, so
// components that read a namespace don't get new labels on every render.
type MemoNode = { next: WeakMap<object, MemoNode>; result?: object };
const memoRoot: MemoNode = { next: new WeakMap() };
const SKIPPED = {};
const BOUNDARY = {};

function memoNode(keys: readonly object[]) {
  let node = memoRoot;
  for (const key of keys) {
    let child = node.next.get(key);
    if (!child) {
      child = { next: new WeakMap() };
      node.next.set(key, child);
    }
    node = child;
  }
  return node;
}

function merge(dictionaries: readonly Layer[], overrides: readonly Layer[]) {
  const sections: Record<string, object> = {};
  for (const layer of [...dictionaries, ...overrides]) {
    for (const [name, section] of Object.entries(layer ?? {})) {
      if (name !== "functions") sections[name] = { ...sections[name], ...(section as object) };
    }
  }
  // Factories run on the merged sections, so an override of a label reaches the
  // functions built from it. All of them run, weakest first: a pack may bring only
  // some functions, and the rest fall through.
  const factories = dictionaries.flatMap((layer) => (layer?.functions as Factory) ?? []);
  const plain = overrides.map((layer) => layer?.functions as object | undefined);
  if (factories.length === 0 && !plain.some(Boolean)) return sections;
  const built = factories.map((factory) => factory(sections));
  return { ...sections, functions: Object.assign({}, ...built, ...plain) };
}

/** Layers go from weakest to strongest; `undefined` layers are skipped. */
export function resolveNamespace<C extends NamespaceConfig>(
  dictionaries: readonly (PackNamespace<C> | undefined)[],
  overrides: readonly (NamespaceOverrides<C> | undefined)[] = [],
): C {
  const node = memoNode([
    ...dictionaries.map((layer) => layer ?? SKIPPED),
    BOUNDARY,
    ...overrides.map((layer) => layer ?? SKIPPED),
  ]);
  node.result ??= merge(dictionaries as readonly Layer[], overrides as readonly Layer[]);
  return node.result as C;
}

function parse(locale: string) {
  try {
    const { language, script } = new Intl.Locale(locale);
    return { language, script };
  } catch {
    return undefined;
  }
}

function matchOne(requested: string, available: readonly string[]) {
  const target = parse(requested);
  if (!target) return undefined;
  const lower = requested.toLowerCase();
  const exact = available.find((locale) => locale.toLowerCase() === lower);
  if (exact) return exact;
  const candidates = available.filter((locale) => parse(locale)?.language === target.language);
  return (
    candidates.find((locale) => target.script && parse(locale)?.script === target.script) ??
    candidates.find((locale) => locale.toLowerCase() === target.language) ??
    candidates[0]
  );
}

/** Exact, then language + script, then language, then any region of the language. */
export function matchLocale(requested: string | readonly string[], available: readonly string[]) {
  for (const locale of typeof requested === "string" ? [requested] : requested) {
    const match = matchOne(locale, available);
    if (match) return match;
  }
  return undefined;
}

export function negotiateLocale(
  requested: string | readonly string[],
  available: readonly string[],
  fallback: string,
) {
  return matchLocale(requested, available) ?? fallback;
}

/** The locales of an Accept-Language header, by quality, without `*`. */
export function parseAcceptLanguage(header: string | null | undefined) {
  if (!header) return [];
  return header
    .split(",")
    .map((part) => {
      const [tag = "", ...params] = part.trim().split(";");
      const quality = params.find((param) => param.trim().startsWith("q="));
      return { tag: tag.trim(), q: quality ? Number(quality.trim().slice(2)) : 1 };
    })
    .filter(({ tag, q }) => tag !== "*" && q > 0 && parse(tag) !== undefined)
    .sort((a, b) => b.q - a.q)
    .map(({ tag }) => tag);
}

/** Empty on the server, where `navigator` exists too and names the machine's language. */
export function getBrowserLocales(): string[] {
  return typeof document === "undefined" ? [] : [...navigator.languages];
}

"use client";

import * as React from "react";
import { I18nProvider } from "react-aria-components";
import type {
  FmaMessagesPack,
  FmaOverrides,
  NamespaceOverrides,
  PackNamespace,
} from "./i18n-types";
import { resolveNamespace } from "./merge";
import {
  createStore,
  type FmaI18nStore,
  type FmaLocales,
  pendingFmaMessages,
  readFmaMessages,
  type StoreOptions,
} from "./store";

type FmaLocaleControls = {
  locale: string;
  locales: readonly string[];
  isPending: boolean;
  setLocale: (locale: string) => void;
};

type FmaI18nContextValue = FmaLocaleControls & {
  active?: FmaMessagesPack;
  fallback?: FmaMessagesPack;
  overrides?: FmaOverrides;
};

const FmaI18nContext = React.createContext<FmaI18nContextValue | null>(null);

const NO_LOCALES: FmaLocales = {};

export type FmaI18nProviderProps = Partial<StoreOptions> & {
  children: React.ReactNode;
  /** Controlled: wins over everything; `setLocale` only calls `onLocaleChange`. */
  locale?: string;
  overrides?: FmaOverrides;
  onLocaleChange?: (locale: string) => void;
  /** Shown while the first pack loads. */
  fallback?: React.ReactNode;
};

/** Puts every registry item in one language. Optional: without it, items render English. */
export function FmaI18nProvider({
  children,
  locale: controlled,
  locales = NO_LOCALES,
  overrides,
  onLocaleChange,
  fallback,
  defaultLocale,
  fallbackLocale,
  initialLocale,
  detect,
}: FmaI18nProviderProps) {
  const [store] = React.useState(() =>
    createStore({
      locales,
      defaultLocale,
      fallbackLocale,
      initialLocale: controlled ?? initialLocale,
      detect,
    }),
  );
  const { locale, isPending } = React.useSyncExternalStore(
    store.subscribe,
    store.getSnapshot,
    store.getSnapshot,
  );

  // A layout effect, so a pack that is already loaded switches before paint.
  React.useLayoutEffect(() => {
    if (controlled !== undefined) void store.setLocale(controlled);
  }, [store, controlled]);

  const isControlled = controlled !== undefined;
  const setLocale = React.useCallback(
    (next: string) => {
      if (isControlled) onLocaleChange?.(next);
      else void store.setLocale(next).then(() => onLocaleChange?.(store.getSnapshot().locale));
    },
    [store, isControlled, onLocaleChange],
  );

  const controls = React.useMemo<FmaLocaleControls>(
    () => ({ locale, locales: store.available, isPending, setLocale }),
    [store, locale, isPending, setLocale],
  );

  // The boundary lets the store commit before a pack suspends: without it, React drops
  // the store on the first mount and every attempt starts over, loading again.
  return (
    <React.Suspense fallback={fallback}>
      <LoadedMessages store={store} controls={controls} overrides={overrides}>
        {children}
      </LoadedMessages>
    </React.Suspense>
  );
}

function LoadedMessages({
  store,
  controls,
  overrides,
  children,
}: {
  store: FmaI18nStore;
  controls: FmaLocaleControls;
  overrides?: FmaOverrides;
  children: React.ReactNode;
}) {
  const { locale } = controls;
  for (const needed of [locale, store.fallbackLocale]) {
    const pending = pendingFmaMessages(store.locales, needed);
    if (pending) React.use(pending);
  }

  const value = React.useMemo<FmaI18nContextValue>(
    () => ({
      ...controls,
      active: readFmaMessages(store.locales, locale),
      // In English the items' own text is the language, so no fallback goes over it.
      fallback: locale === "en" ? undefined : readFmaMessages(store.locales, store.fallbackLocale),
      overrides,
    }),
    [store, controls, locale, overrides],
  );

  return (
    <FmaI18nContext.Provider value={value}>
      <I18nProvider locale={locale}>{children}</I18nProvider>
    </FmaI18nContext.Provider>
  );
}

/** A namespace's texts: the prop, over `overrides`, over the active language, over `english`. */
export function useFmaMessages<K extends keyof FmaNamespaces>(
  namespace: K,
  english: PackNamespace<FmaNamespaces[K]>,
  prop?: NamespaceOverrides<FmaNamespaces[K]>,
): FmaNamespaces[K] {
  const context = React.useContext(FmaI18nContext);
  type Layer = PackNamespace<FmaNamespaces[K]>;
  return resolveNamespace<FmaNamespaces[K]>(
    [english, context?.fallback?.[namespace] as Layer, context?.active?.[namespace] as Layer],
    [context?.overrides?.[namespace] as NamespaceOverrides<FmaNamespaces[K]>, prop],
  );
}

/** The language and its switch, for a selector; `null` without a provider. */
export function useFmaLocale(): FmaLocaleControls | null {
  const context = React.useContext(FmaI18nContext);
  return React.useMemo(
    () =>
      context && {
        locale: context.locale,
        locales: context.locales,
        isPending: context.isPending,
        setLocale: context.setLocale,
      },
    [context],
  );
}

import type { FmaMessagesPack } from "./i18n-types";
import { getBrowserLocales, matchLocale, negotiateLocale } from "./negotiate";

// Bundlers replace process.env.NODE_ENV at build time; declared here so
// consumers without @types/node still compile.
declare const process: { env: { NODE_ENV?: string } };

export type FmaLoader = () => Promise<{ default: FmaMessagesPack }>;
/** Locale → pack or loader. "en" is always available: it's the lib's English. */
export type FmaLocales = Record<string, FmaMessagesPack | FmaLoader>;

export type StoreOptions = {
  locales: FmaLocales;
  defaultLocale?: string;
  fallbackLocale?: string;
  initialLocale?: string | readonly string[];
  detect?: boolean;
};

export type FmaI18nSnapshot = { locale: string; isPending: boolean };

export interface FmaI18nStore {
  readonly locales: FmaLocales;
  readonly available: readonly string[];
  readonly fallbackLocale: string;
  getSnapshot(): FmaI18nSnapshot;
  subscribe(listener: () => void): () => void;
  setLocale(locale: string): Promise<void>;
}

// Packs are immutable, so sharing them across server requests is safe.
// Everything per-user lives in a store.
const loading = new WeakMap<FmaLoader, Promise<FmaMessagesPack>>();
const loaded = new WeakMap<FmaLoader, FmaMessagesPack>();

function load(loader: FmaLoader) {
  let promise = loading.get(loader);
  if (!promise) {
    promise = loader().then(
      (module) => {
        loaded.set(loader, module.default);
        return module.default;
      },
      (error: unknown) => {
        loading.delete(loader);
        throw error;
      },
    );
    loading.set(loader, promise);
  }
  return promise;
}

const availableLocales = (locales: FmaLocales) => [...new Set(["en", ...Object.keys(locales)])];

/** The pack if it is an object or already loaded; undefined otherwise. */
export function readFmaMessages(locales: FmaLocales, locale: string) {
  const entry = locales[locale];
  return typeof entry === "function" ? loaded.get(entry) : entry;
}

/** The loader's promise while `locale` isn't readable yet; stable, so React `use` can take it. */
export function pendingFmaMessages(locales: FmaLocales, locale: string) {
  const entry = locales[locale];
  return typeof entry === "function" && !loaded.has(entry) ? load(entry) : undefined;
}

/** Loads the pack and its fallback once per loader; resolves the negotiated locale. */
export async function loadFmaMessages(
  locales: FmaLocales,
  requested: string | readonly string[],
  fallbackLocale = "en",
) {
  const locale = negotiateLocale(requested, availableLocales(locales), fallbackLocale);
  await Promise.all([
    pendingFmaMessages(locales, locale),
    pendingFmaMessages(locales, fallbackLocale),
  ]);
  return locale;
}

function negotiateOrWarn(requested: string | readonly string[], store: FmaI18nStore) {
  const match = matchLocale(requested, store.available);
  if (match) return match;
  if (process.env.NODE_ENV !== "production") {
    console.warn(`[fma-i18n] No locale matches ${requested}; using ${store.fallbackLocale}.`);
  }
  return store.fallbackLocale;
}

/** One per provider instance, never a singleton: that keeps server requests apart. */
export function createStore(options: StoreOptions): FmaI18nStore {
  const { locales, defaultLocale = "en", fallbackLocale = defaultLocale, initialLocale } = options;
  const available = availableLocales(locales);
  const listeners = new Set<() => void>();
  let request = 0;

  const emit = () => {
    for (const listener of listeners) listener();
  };

  const store: FmaI18nStore = {
    locales,
    available,
    fallbackLocale,
    getSnapshot: () => snapshot,
    subscribe(listener) {
      listeners.add(listener);
      return () => listeners.delete(listener);
    },
    async setLocale(requested) {
      const locale = negotiateOrWarn(requested, store);
      const current = ++request;
      if (locale === snapshot.locale && !snapshot.isPending) return;
      const ready =
        !pendingFmaMessages(locales, locale) && !pendingFmaMessages(locales, fallbackLocale);
      if (!ready) {
        snapshot = { ...snapshot, isPending: true };
        emit();
        try {
          await loadFmaMessages(locales, locale, fallbackLocale);
        } catch (error) {
          if (current === request) {
            snapshot = { ...snapshot, isPending: false };
            emit();
          }
          throw error;
        }
        // A newer request took over while this pack loaded.
        if (current !== request) return;
      }
      snapshot = { locale, isPending: false };
      emit();
    },
  };

  const detected = options.detect === false ? [] : getBrowserLocales();
  let snapshot: FmaI18nSnapshot = {
    locale:
      initialLocale !== undefined
        ? negotiateOrWarn(initialLocale, store)
        : negotiateLocale(detected, available, defaultLocale),
    isPending: false,
  };
  return store;
}
